-- v375 · Panel Interactivo de Seguimiento de Marketing (reuniones de procesos).
--   s:SEG_ACCESS   quién ve el panel (lista de personas). La leen todos; la cambia solo Admin total.
--   s:SEGUIMIENTO  las iniciativas (MKT-###), las reuniones, los avances de cada iniciativa y los temas para la próxima
--                  reunión. La leen y la guardan solo las personas de s:SEG_ACCESS y Admin total; el resto ni la baja.
-- De arranque lo ven Fede, Alyssa, Emanuel y Patricia. Para sumar a alguien (por ejemplo Enrique, Marlene o Helena
-- cuando tengan usuario), Admin total lo tilda en el panel (“Quién lo ve”): no hace falta otra migración.
-- La función es la misma de 20261120120000_video_retail_mkt_hub.sql (v374, con s:APP_VIDEO) con una línea más (s:SEGUIMIENTO).

create or replace function private.can_access_state(p_key text, p_data jsonb)
 returns boolean
 language sql
 stable security definer
 set search_path to ''
as $function$
  select case
    when private.my_person_id() is null then false
    when private.is_revisor() then p_key in ('s:PEOPLE', 's:APP_FLAGS', 's:PRESENCE', 's:INBOX_DONE', 's:META_INBOX', 's:META_DM', 's:META_DM_LOG', 's:META_IG_ACT', 's:META_POSTS')
    when private.is_comercial() then p_key in ('s:PEOPLE', 's:APP_FLAGS', 's:PRESENCE', 's:PEDIDOS_COM', 's:COMERCIAL', 's:META_FOLLOWERS', 's:META_DEMO', 's:META_POSTS', 's:CAMP_FOLDERS')
    when p_key like 'notes:%' or p_key like 'prompts:%' or p_key like 'comchk:%' then split_part(p_key, ':', 2) = private.my_person_id()
    when p_key like 'thread:%' then not private.no_chat() and private.my_person_id() in (p_data->>'a', p_data->>'b')
    when p_key like 'chat:%' then not private.no_chat() and exists (
      select 1
      from public.app_state g
      cross join lateral jsonb_array_elements(case when jsonb_typeof(g.data) = 'array' then g.data else '[]'::jsonb end) e
      where g.key = 's:CHAT_GROUPS'
        and e->>'id' = substr(p_key, 6)
        and (
          coalesce((e->>'all')::boolean, false)
          or coalesce(e->'members', '[]'::jsonb) ? private.my_person_id()
          or exists (select 1 from public.members m where m.user_id = auth.uid() and m.active and coalesce(e->'roles', '[]'::jsonb) ? m.role)
        )
    )
    when p_key in ('s:SUGGESTIONS', 's:SURVEYS', 's:DRAFTS') then private.is_admin_total()
    when p_key = 's:INFLUENCERS' then exists (select 1 from public.members m where m.user_id = auth.uid() and m.active and m.role in ('Admin total', 'CM'))
    when p_key in ('s:META_INBOX', 's:RECLAMOS', 's:ESCRACHES', 's:META_DM', 's:META_DM_LOG', 's:META_IG_ACT') then exists (select 1 from public.members m where m.user_id = auth.uid() and m.active and m.role in ('Admin total', 'Admin', 'CM'))
    when p_key in ('s:AGENTS', 's:AGENT_CHAT', 's:CRONOGRAMA', 's:APP_VIDEO') then exists (select 1 from public.members m where m.user_id = auth.uid() and m.active and m.role in ('Admin total', 'Admin'))
    when p_key = 's:SEGUIMIENTO' then private.is_admin_total() or exists (
      select 1 from public.app_state a
      where a.key = 's:SEG_ACCESS' and jsonb_typeof(a.data) = 'array' and a.data ? private.my_person_id()
    )
    else p_key like 's:%'
  end
$function$;

-- Quién ve el panel: lo cambia solo Admin total.
drop policy if exists "app_state: acceso seguimiento solo admin total (modificar)" on public.app_state;
create policy "app_state: acceso seguimiento solo admin total (modificar)" on public.app_state as restrictive for update
  using (key <> 's:SEG_ACCESS' or private.is_admin_total())
  with check (key <> 's:SEG_ACCESS' or private.is_admin_total());
drop policy if exists "app_state: acceso seguimiento solo admin total (crear)" on public.app_state;
create policy "app_state: acceso seguimiento solo admin total (crear)" on public.app_state as restrictive for insert
  with check (key <> 's:SEG_ACCESS' or private.is_admin_total());

-- De arranque: Fede, Alyssa, Emanuel y Patricia.
insert into public.app_state (key, data) values ('s:SEG_ACCESS', '["fede","alyssa","emanuel","patricia"]'::jsonb)
on conflict (key) do nothing;

